    const result = sfc.parse(source, { filename: file });
    assert.equal(result.errors.length, 0);
    return result.descriptor;
}
function normalize(value, key = '') {
    if (Array.isArray(value)) return value.map(v => normalize(v));
    if (!value || typeof value !== 'object') return value;
    // Only the two branches of an if may acquire a one-statement block.
    if ((key === 'consequent' || key === 'alternate') && value.type === 'BlockStatement' && value.body.length === 1) return normalize(value.body[0]);
