assert.equal(candidate.split(newFocus).length, 2);
assert.equal((candidate.match(/\bvoid nextTick\(/g) || []).length, (base.match(/\bvoid nextTick\(/g) || []).length + 1);
const scriptAsts = [before,after].map(d => normalize(babel.parse(d.scriptSetup.content, { sourceType:'module', plugins:['typescript'] }).program));
assert.deepEqual(scriptAsts[0],scriptAsts[1]);
assert.equal(before.template.content, after.template.content);
const templates = [before,after].map(d => {
    const compiled = sfc.compileTemplate({ source:d.template.content, filename:file, id:'outline-source-static', compilerOptions:{ mode:'module' } });
    assert.equal(compiled.errors.length,0);
    return compiled.code;
});
assert.equal(templates[0],templates[1]);
const emits = [before,after].map(d => {
    const script = sfc.compileScript(d,{ id:'outline-source-static' });
    const emitted = ts.transpileModule(script.content,{ compilerOptions:{ target:ts.ScriptTarget.ES2022, module:ts.ModuleKind.ESNext }, reportDiagnostics:true });
    assert.equal((emitted.diagnostics || []).filter(x=>x.category===ts.DiagnosticCategory.Error).length,0);
    return normalize(babel.parse(emitted.outputText,{ sourceType:'module' }).program);
});
assert.deepEqual(emits[0],emits[1]);
assert.equal(before.styles.length,1); assert.equal(after.styles.length,1);
function cssTree(source) {
    return postcss.parse(source).nodes.map(function visit(n) {
        const result = { type:n.type };
        for(const key of ['selector','prop','value','important','name','params','text']) if(n[key] !== undefined) result[key] = n[key];
        if(result.name === 'media' && result.params === '(max-width: 1023px)') result.params = '(width <= 1023px)';
