    },
    digests:{ base_source_sha256:hash(base),candidate_source_sha256:hash(candidate),normalized_script_ast_sha256:hash(scriptAsts[0]),template_emit_sha256:hash(templates[0]),normalized_script_emit_ast_sha256:hash(emits[0]),normalized_css_ast_sha256:hash(cssTrees[0]) }
};
fs.writeFileSync('/tmp/outline-static-review-result.json',JSON.stringify(evidence,null,4)+'\n');
